INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987122-me204', 'stk-user5216', 'ME 204', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nجودة المقرر بشكل عام : ممتاز ويعطيك فكره اوسع عن الثيرموداينامكس\n\nالمواضيع التي يغطيها المقرر :\nExergy + Gas Power Cycle + Vapor and combined Cycles + Refrigeration cycle + Gas Mix + Chemical Reactions\n\nالكتاب المستخدم للمقرر : ممتاز ( نفس كتاب ME203 )\n\nالأسئلة والأمثلة المستخدمة في المقرر : كافيه وانصح بالاعتماد عليها\n\nطريقة دراسة المقرر :\n1 - اقرأ الكتاب\n2 - فهم الامثلة الي موجوده في الكتاب واعادة حلها\n3 - حل اسئلة الهومورك بنفسك والاسئلة المشابهه له لو فيه وقت\n4 - ( واهم شي انك تشتغل على الفورملا شيت من البداية - كل تشابتر تذاكرة وتحل هوموركه لخص الفورملاز حقته بورقه خارجيه ) عشان قبل المياجر بس تحتاج ترتب الفورملاز كلها بفورملا شيت واحدة\nوصدقني كل مازبطت الفورملاشيت حقتك كل ماارتحت قبل الاختبار واثناء الاختبار\n\nاضافة : ينصح بالرجوع لـ تشابتر ME203 ch7 عند مراجعة تشابتر 8\n, وبالتوفيق ,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/120733/2", "user": "user5216", "ts": 1329316308000, "tid": 120733, "pn": 2}}', 1329316308000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1162584-me204', 'stk-aziz_saleem', 'ME 204', 'info', '{"desc": "الفورميلا شيت من القسم ,\n\nملاحظات :\n- راح تدرسوا سايكلز كثيييييره في الكورس دا و راح تعتمدوا في فهمها على الـ T-s and P-v diagrams , نصيحة لا تحفظها و افهم كل قطعة في السايكل ايش تسوي سوا في درجة الحرارة او الضغط أو اي خاصية تانيه لأنه هذا البارت هوا اللي يتشابه في كل السايكلز , تفهمه و راح يسهل عليك فهم السؤال في الميجر و تحله بدون مشاكل ان شاء الله ,\n\n- الفاينل حقها شامل كل المنهج , لا تتحمس و تأجل مذاكرتها , رتب وقتك من بدري ,\n\n- الكلاس وورك عليه 35% (كويزات +هومووراكت+ بروجكت) , ( يعني أكثر من الفاينل 30% ) , اذا انت من النوع اللي يحسب على الهوم ووركات و الكويزات لازم تنتبه منها ,\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/120733/12", "user": "aziz_saleem", "ts": 1357958320000, "tid": 120733, "pn": 12}}', 1357958320000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1228970-me204', 'stk-s2010xxxxx', 'ME 204', 'info', '{"desc": "جودة المقرر بشكل عام : ممتاز\nالمواضيع التي يغطيها المقرر : السايكلز والافشنسي\nالكتاب المستخدم للمقرر: ممتاز\nالأسئلة والأمثلة المستخدمة في المقرر: جيده\nمدى فائدته في الناحية التطبيقية: ملحوظه بشكل كبير\n\nالماده تقريبا اصعب بشوي من ثيرمو 1 واصعب شي فيها اول تشابتر , بعدين تكون الماده سهله , الفاينل راح يغطي المنهج كامل لذلك نصيحه ابدا فيها من بدري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/120733/13", "user": "s2010xxxxx", "ts": 1369689611000, "tid": 120733, "pn": 13}}', 1369689611000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438147-me204', 'stk-dyaa94', 'ME 204', 'info', '{"desc": "ثرمو 2…151\n\nكورس جدا مفيد في الناحية العملية…راح يفيدك كثير في مستقبلك المهني…راح تدرس سايكلز كثيره منها مكينة السياره ومحطات توليد الكهرباء الخ.\n\nفي الكورس ذا راح تطبق اللي اخذته في ثرمو 1 ف نصيحه اخذه بعد ثرمو 1 على طول لانه جدا مهم.\n\nاصعب شوي من 1 بس تقدر عليه…\n\nالفورملا شيت تسويها بنفسك ونصيحتي لاتاخذ جاهزه من احد بعد ماتخلص مذاكرة اكتبها بنفسك وراح تستفيد اكثر…\n\nكورس كان جدا ممتع وبالتوفيق للكل…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/120733/15", "user": "Dyaa94", "ts": 1452075748000, "tid": 120733, "pn": 15}}', 1452075748000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504231-me204', 'stk-mohammed_sahwan', 'ME 204', 'info', '{"desc": "181\nجودة المقرر:\nممتاز جدا A+\nالمواضيع التي يغطيهى المقرر:\nفي المرفق\nالكتاب المستخدم:\nفي المرفق. ( من المحتمل تغيير الكتاب إلى principles of engineering thermodynamics)\nنظام الدرجات:\nفي المرفق\nطريقة المذاكرة:\nشرح الكتاب كان أكثر من ممتاز بالإضافة إلى التواجد الذهني في الليكشر\nفائدته من الناحية التطبيقية:\nمفيد جدا A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/120733/16", "user": "Mohammed_Sahwan", "ts": 1546120474000, "tid": 120733, "pn": 16}}', 1546120474000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1510749-me204', 'stk-3mmarooof', 'ME 204', 'info', '{"desc": "المادة اخذتها ترم 182 …\n\nالمادة حلوة وممتعة … لكن يبيلها شغل وتفتيح مخ\n\nنزلت المادة على اساس انه الاولون الاسبقون يدخلون الاختبارات ومعهم فورملا شيت يسوونها بانفسهم … لكن الترم ذا م كان فيه الكلام ذا …المياجر كانت في فورملا شيت من الانسنتركتر نفسه …مدري عن باقي السكاشن هل اعطوهم او لا … لكن الفاينل فوق انه شامل لمتيريل الميجر الاول والثاني م كان فيه فورملا شيت م عدا معادلتين بس حق اسئلة اختيارات وحقت تشابتر 11 في الكتاب الجديد حق موران (كثر خيرهم ) … وبس والله … نقول ان شاء الله الاترام الجاية القسم يتعوذ من ابليس وبحط فورملا شيت زي البني ادمين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/120733/18", "user": "3mmarooof", "ts": 1560117631000, "tid": 120733, "pn": 18}}', 1560117631000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527084-me204', 'stk-ahm2d1', 'ME 204', 'info', '{"desc": "جودة المقرر بشكل عام: ممتاز ويعطيك افكار اوسع عن الثيرمو.\n\nالمواضيع التي يغطيها المقرر: Exergy + Gas Power Cycle + Vapor and combined Cycles + Refrigeration cycle + Gas Mix + Chemical Reactions\n\nالكتاب المستخدم للمقرر: الكتاب جيد وفيه امثله كثيره بس المشكله ماله سلوشن مانوال, يعني لو بغيت تتدرب على اسئلة ما بتعرف حلك صح او لا.\nالأسئلة والأمثلة المستخدمة في المقرر: جيده وافكارها قريبه من الاختبارات.\n\nملاحظات: الكورس مو صعب بس مقارنة ب 203 يعتبر اصعب شوي واطول من ناحية الماتيريل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/120733/19", "user": "Ahm2d1", "ts": 1607930134000, "tid": 120733, "pn": 19}}', 1607930134000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530167-me204', 'stk-abofordan2004', 'ME 204', 'info', '{"desc": "TERM 202 ONLINE\n\nكورس متوسط ومواضيعه بدايتها عن ال exergy و Cycles كتبريد او تسخين ونهايته عبارة عن كيمياء 101 لكن بتعمق شوي\n\nالدروس متوسطة الصعوبة ولكن اصعبها اول تشابتر اللي هو الاكسرجي , بس افتح مقاطع محمد شايع على اليوتيوب وتتسهل باذن الله\n\nانتبه من الكويزات اذا انت تدرس اون لاين لا تدخلها الا وانت حال اولد اقزام لانهم مصعبينها و نص القريد عليها\n\nشخصيا المادة عجبتني اكثر من ثيرمو 1 مع اني جبت فيها قريد اقل .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/120733/20", "user": "AboFordan2004", "ts": 1622373376000, "tid": 120733, "pn": 20}}', 1622373376000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p569457-me204', 'stk-user6511', 'ME 204', 'info', '{"desc": "السلام عليكم ورحمة الله …\n\nشباب اللي عنده سلايدات لل me 204 يرفعها او يرسلها على الايميل just\\_person\\_89@hotmail.com ضروري الله يوفقكم الاختبار بعد يومين و ماني عارف اذاكر من الكتاب لان الترم اللي راح كنت عند السرخي و يشرح من سلايدات . واللي ماعنده و يعرف نوت ممتاز يعلمنا عنه ضروري .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/85680/1", "user": "user6511", "ts": 1269015573000, "tid": 85680, "pn": 1}}', 1269015573000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1028122-me204', 'stk-mechanical_boy', 'ME 204', 'info', '{"desc": "مانصحك تاخذ حتى لو لقيت الماده ذي بالذات لازم تكون فاهم وش مكتوب بالفورمولا شيت وطريقه الحل ورسمات السايكلز واشياء كثير انت لما تراجع طرق حل الهومورك والاختبارات القديمه راح تلاقي ان طريقه الحل اغلب الاحيان ثابته فاكتبها بنفسك حتى تكون فاهم كل شي وانصحك تلقي نظره عالمياجر القديمه لان الترم الي راح جابو نفس الافكار بالضبط\n\nوفالك التوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wanted-me204-formula-sheet-major-2/124758/2", "user": "Mechanical_Boy", "ts": 1335303898000, "tid": 124758, "pn": 2}}', 1335303898000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p822369-me204', 'stk-user3687', 'ME 204', 'info', '{"desc": "انا كنت اذاكر من السليوشن مانول اسئله الهوم وركـ\nوطلعت بدرجه ممتازه\n\nبس بشكل عام المياجر السمستر الماض كانت تافهه وسهله لابعد درجه كلها ميجر ون ومبجر تو\n\nكان الهوم ورك اصعب منها … لدرجه ان ودي كل المواد تصير ثيرمو تو 🙂\n\nواذا وانت تذاكر الهوم ورك استقعدلك سوال اكتب فكرت حله بالفورميلا شيت\n\nوصح على طاري الفورميلا شيت كنت اكتبها بخط صغير واحط فيها الكتاب كله ومن سهوله المبجر ادخل واطلع وهي بجيبي ما دريت عنها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me204/105471/3", "user": "user3687", "ts": 1300880721000, "tid": 105471, "pn": 3}}', 1300880721000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1041340-me204', 'stk-amat_24', 'ME 204', 'info', '{"desc": "انا اتكلم عن 111 (يعني السمستر الماضي)\nانا نزلت المادة وقتها،، اكثر من النص بشوية كان على القديم، ومتذكر سؤال كامل طويل عن السايكل كان فيه 6 ستيتس\n\nوعلى ذمة واحد من الشباب اخذها في 101 مدري 102 يقولي جاهم الاختبار زي ما وصفته له\n\nمدري يمكن غيرو رايهم هذا السمستر. بس اللي جانا اكثر من نصه بشوية كان على القديم\nحتى الاقزيرشي جابوه، بس اعتقد كان في الاختيارات بس\n\nبالنسبة للجديد، ركزو على البلنس حق المعدلات الكيميائية لانه حرام تضيعو درجات في شي تافه زي كذا (كانت مطلوبة في سؤالين، مرة بلنس بس، ومرة بلنس وتكمل حل بعدها)\nوجا سؤال عن التكييف على ما اتذكر، كان يحتاج السايكومترك تشارت\nوطبعا فيه اسئلة عن البارشل دريفتفز\n\nلا تضيع وقتك على الاختيارات قبل ما تحل المسائل الكتابية كاملة، الاختيارات تضيع وقتك ووزنها اقل من الكتابية، اياك تلمسها الا في نهاية الاختبار، عشان تسوي قس لو خلص الوقت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/125924/13", "user": "amat_24", "ts": 1337641437000, "tid": 125924, "pn": 13}}', 1337641437000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1370462-me204', 'stk-old_oria', 'ME 204', 'info', '{"desc": "سمستر 131\nالفاينل جانا سؤالين اختيارات كل سؤال فيه 10 فقرات كل فقرة عليها 2.5\nيعني توتال الاختيارات 50 يعني نص الفاينل طبعا كله من الماتيريال القديم اللي قبل الفاينل\nوجانا سؤالين كتابي من الماتيريال الجديد على كل سؤال 25 درجة يعني اثنينهم 50\nويصير التوتال 100\nعالعموم الفاينل كان متوسط مائل للسهولة الريتن سهل مجرد تطبيق\nوالاختيارات متوسطة وبعضها شوي صعبة\nبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me204/161377/5", "user": "old_oria", "ts": 1400937256000, "tid": 161377, "pn": 5}}', 1400937256000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438571-me204', 'stk-abo_yazeed6', 'ME 204', 'info', '{"desc": "أنا مثلك أخذت ثريمو 1 مع شاهين\n\nو بعد سنة أخذت ثيرمو 2 مع الفرائضي\n\nبالنسبة لي ثيرمو 2 أسهل بمراحل من ثيرمو 1 ,وقريدي فيها أعلى من قريدي في ثيرمو 1\n\nبالنسبة لرد الأخ اللي فوقي ,نعم تحتاج تكون فاهم الأساسيات في ثيرمو 1 لكن مو كل التفاصيل,وعموما الدكتور راح يشرح لك الأشياء الي تحتاج تتذكرها.\n\nأذكر أول كلاس الفرائضي خلاه مراجعة للأشياء المهمة في ثيرمو 1 ,بشكل عام فيه ترابط كبير بين أول شابتر في ثيرمو 2 اللي هو الاكسيرجي وبين ماتيريال ثيرمو 1 ,لكن الشباتر اللي بعدها حتى لو كنت ناسي ماتيريال ثيرمو 1 راح يمديك تحل مسائله وتتذكر كل شيء بسهولة.\n\nأهم شيء في ثيرمو 2 ضبط لك فورملا شيت ,لأنه قوانينه كثيرة ومسموح بالفورملا شيت في الامتحانات ,ارسم الفيقرز (T vs S) و (P vs V) للسايكلز الي راح تدرسها واحفظ وارسم أجزاء الـ Engines اللي راح تدرسها بعد,قد ما ترتب الفورملا شيت قد ما تجيب قريد عالي بإذن الله.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me204/171508/3", "user": "abo_yazeed6", "ts": 1452506440000, "tid": 171508, "pn": 3}}', 1452506440000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p418540-me204', 'stk-user2872', 'ME 204', 'info', '{"desc": "معليش اسمح لي اخي الفاضل\n\nانا منزل المادة الترم هذا مع الدكتور محمد حبيب\n\nالتشابتر الاخير مو زي ما تقول جلس فيه كلاسين\n\nبالعكس جلس فيه اكثر من 8 كلاسات وشرح لنا الماتيريال مزبووط قبل الاختبار\n\nبالنسبة للسؤال الاول … وشلون تقول انه من خارج الكتاب … هذي هي الـ Rankine cycle واللي جت للطلاب في ميجر ون وجتهم في البروجكت … وموجودة في الكتاب شرح كامل للCycle >> فاسمح لي اقول لك غلطان في هذي وانهم جابوا المسألة من خارج الكتاب … وييين مستحييل\n\nالسؤال الاخير كان عادي ودكتورنا شرحه لنا بالتماام والكمال وقال لنا طريقة حله ونبهنا على الاغلاط اللي يسوونها الطلاب في مثل هالسؤال … فما اتوقع فيه صعوبة\n\nالسؤال الثاني كان سهل جدا\n\nالسؤال الثالث بفقرتينه ما عرفت حلها ومع هذا موجودة في اسألة الهوم وورك\n\nالا على فكرة مين دكتورك\n\nانا ما اقول الاختبار سهل … بالعكس كان صعب جدا ويبي له وقت طويييل للتفكير … يعني ساعتين ونص ما هي كافيات ابد أبد\n\nعموما بالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/74417/2", "user": "user2872", "ts": 1245755936000, "tid": 74417, "pn": 2}}', 1245755936000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1262222-me204', 'stk-eng.mshari', 'ME 204', 'info', '{"desc": "السلام عليكم …\n\nشباب اواجه صعوبة في دراسة هذا الكورس … الصعوبة تكمن في عدم وجود سورس معين ادرس منه … يعني من نوت دكتور او سلايدات او من الكتاب … 😞\n\nالدكتور اللي انا معه نوتته حقت الكلاس حشو كلام فاضي ومافيها شرح واضح عن صلب الموضوع … 🤪\n\nآرائكم … وش افضل سورس ادرس منه …\n\nمشكورين … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204-thermodynamics-ii/149339/1", "user": "Eng.Mshari", "ts": 1378827991000, "tid": 149339, "pn": 1}}', 1378827991000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1003424-me204', 'stk-metallic', 'ME 204', 'info', '{"desc": "شف أنا درست عنده 203 وألحين آخذ معه 204 … الرجال أحسن منه ما تلقى أبدا …\n\nوترا الكلاس تست ماعليه الا 10 بالمية فقط … وعندك كلاس تست ثاني ومياجر وكلاس وورك وفاينل يعني ماراح شيء أبداً ! … أنا يوم كنت ب 203 عنده، أخذت بالكلاس تست اللويست في السكشن والميجر الأول ما بيني وبين اللويست شيء 🤠 … بس شديت بالميجر الثاني والفاينل والكلاس وورك خذت فيه أظن 16 وشوي من 20 والحمدلله طلعت بقريد أعلى من المتوقع … لدرجة أني صرت أعلى من الأفرج النهائي للمادة! … فنصيحتي ترا المادة ممتعة جداً فلا يفوتك القطار … شد في الباقي واستمتع بها … والله يوفقنا جميعاً … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me204/122527/4", "user": "METALLIC", "ts": 1331256239000, "tid": 122527, "pn": 4}}', 1331256239000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p976920-me204', 'stk-_004', 'ME 204', 'info', '{"desc": "ايش الـ 204 عند الـ 203 أسهل من الـ 203 بوااااااااااااااااااااااجد\nتبدا بالـ Exergy لازم تاخذ فكره عن الـ 203 شابتر 7 وتحل عليها الهوم وركات وامورك عال العال … طبعا تلاحظ إن الأمئلة صعبه حبتين يعني ترا حتى مستوى المياجر أسهل من الأمئلة فحاول تحل الأمثلة قد ما تقدر والهوم وركات\nتبدا من شابتر 9 الcycles هذي أسميها خريطه تمشي عليها من الفورملا شيت حقتك وصلى الله وسلم طبعا الcycle راح تمتد معك لين شابتر 11 ثم شابتر 12 سهالات بس ما دخل مخي ولا حبيته لكن سهل موب صعب اغلبه ماث ثم شابتر 13 بسيط موب صعب الفرق فيه هالشابتر إنك من أول تحل على غاز واحد الحين راح يكون عندك نظام فيه أكثر من غاز يجيك بالفاينل على شكل خيارات بس … 14 حق الهواء وحله بعد ركز فيه ع الهوم وركات نصيحه لوجه الله والامئلة … 15 ياحبي له هالشابتر حلو مرة وزن معادله اهم شي فيه والباقي تعويض مباشر من قانون وقوانينه مش كثيرة\n\nبشكل عام الكورس أسهل من 203 … سهولته في شغله إنك تضبط لك فورملاشيت محترمه تغنيك في الإختبار وكأنه مانيوال سلوشن … وصعوبته في الوقت لإن الوقت ما يسعفك أبد أخطاء النواتج عندي بريال لإني كنت أحط رجلي أول ما امسك الورقه …\n\nركز على :\n1- حاول تسوي فورملا شيت ممتااااااازة لإن غالبا تساعدك بعد الله\n2 - الهوم وركاااااات وعاد تبي الجد جانا منها نسخ لصق بالرقم بعد\n3 - الإختبارات القديمة يجي منها شي طيب وأصلا تب تعرف منها وش اللي يجيبونه ووش اللي يطنشوونه\n\nمن ناحيه النوتات كنت أمشي على حقت مدرسنا أفهم منها وماشي حالها كويسة (( محمد حبيب ))\nوطبعا تبي تنجلط من شابتر 8 وتقول الماده صعبه بس أبشرك هذا يعتبر أصعب الكورس ولاهو صعب\n\nبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me204/119353/4", "user": "_004", "ts": 1327950383000, "tid": 119353, "pn": 4}}', 1327950383000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1186353-me204', 'stk-s_h_a_d_o_w', 'ME 204', 'srcU', '{"html": "هذه نوتات جيدة كنت اذاكر منها ان شاء الله تفيدكم<br><br>​<span data-fid=\"stk-f1186353-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1186353-0": {"name": "me 204 notes.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/05a8565d15750117f4a42b2f12b24db3fbdc95dcadd3cbfbf20de1aab7c23893"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/140641/4", "user": "S_H_A_D_O_W", "ts": 1361222083000, "tid": 140641, "pn": 4}}', 1361222083000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
