INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1138971-me204', 'stk-honest_devil', 'ME 204', 'srcP', '{"html": "رفعت الملف وبالتوفيق ياشباب ولا تنسونا بالدعاء… ❤️<br><br>​<span data-fid=\"stk-f1138971-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f1138971-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1138971-0": {"name": "ME 204-112-design_1.doc", "v": "data:application/msword;base64,"}, "stk-f1138971-1": {"name": "my 204 proj.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/34b67a10ff7fe57c8febd25bcd65d90de9b953f05c91c85ca61bc73a03569030"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/136235/5", "user": "Honest_Devil", "ts": 1355313797000, "tid": 136235, "pn": 5}}', 1355313797000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p936326-me204', 'stk-vip_master', 'ME 204', 'srcU', '{"html": "بروجكت في المرفقات<br><br>راح استعين و ادفع المبلغ لمدرس خصوصي بعد الساعه 12 اليوم ان ما احد رد<br><br>​<span data-fid=\"stk-f936326-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f936326-0": {"name": "ME204.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/115492/3", "user": "VIP_Master", "ts": 1322144254000, "tid": 115492, "pn": 3}}', 1322144254000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1031099-me204', 'stk-a-majeed', 'ME 204', 'srcU', '{"html": "شباب الله لا يهينكم محتاجين مساعدتكم في بورجكت الدكتور محمد حبيب الموجود في المرفقات<br><br>ولكم جزيل الشكر 🌹<br><br>​<span data-fid=\"stk-f1031099-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1031099-0": {"name": "ME 204-112-design_1.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/125057/1", "user": "A-MAJEED", "ts": 1335892502000, "tid": 125057, "pn": 1}}', 1335892502000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p805348-me204', 'stk-_1141', 'ME 204', 'srcP', '{"html": "في المرفقات<br><br>​<span data-fid=\"stk-f805348-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f805348-0": {"name": "ME_204_HW0.102.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/104068/4", "user": "_1141", "ts": 1299193062000, "tid": 104068, "pn": 4}}', 1299193062000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1105308-me204', 'stk-maymdek', 'ME 204', 'srcU', '{"html": "الدكتور محمد حبيب معطينا فورميلا شيت (تقدر تشيك عليها ) يقول هذي اللي بتاخذونها في جميع الاختبارات بس ما فيها ولا سايكل … واشوف انها ما فيها اي فايده 😞 لكن الله يعين<br><br>​<span data-fid=\"stk-f1105308-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1105308-0": {"name": "~$204-Formula sheet_Cengel (1).doc", "v": "data:application/msword;base64,Bk1hcndhbgAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAABgBNAGEAcgB3AGEAbgAAAAcATQBpAG4AZwBMAGkAVQAGAFMAaQBtAFMAdQBuAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAACYQAAAAAAAAAAAAAD/////4GuWAgAAAAAAAAAA"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/133332/3", "user": "maymdek", "ts": 1349728405000, "tid": 133332, "pn": 3}}', 1349728405000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1135117-me204', 'stk-abu_hamad', 'ME 204', 'srcP', '{"html": "الفورملا شيت<br><br>​<span data-fid=\"stk-f1135117-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1135117-0": {"name": "Formula sheet.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/7d3a037bb6a5da3cddfd33e1db4311f7025db5bb75b7c32fe3f64f81a2682fbf"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-204/135990/13", "user": "Abu_Hamad", "ts": 1354991645000, "tid": 135990, "pn": 13}}', 1354991645000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1041513-me204', 'stk-s_h_a_d_o_w', 'ME 204', 'srcP', '{"html": "السلام عليكم<br><br>الفورميلا شيت عبارة عن الفورميلا شيت لميجر 1 + فورميلا شيت ميجر 2 (نفس الي نشرتهم أول) + قوانين شابتر 13 و 14 و 15<br><br>طبعا كالعادة الفوميلا شيت قد تكون غير شاملة و تحتوي على أخطاء و يستحسن انك تسوي الفورميلا شيت بنفسك. لكن لو حبيت تسخدم حقتي لازم تراجعها كويس و تتأكد من ترتيب و أماكن القوانين.<br><br>طريقة الطباعة :<br><br>في المرفقات في ملفين وورد كل ملف فيه صفحتين يعني المجموع 4 صفحات و بما ان الطالب مسموح له صفحتين بس فنحتاج اننا نطبع كل صفحتين في صفحة و الطريقة هي :<br><br>اضغط على File بعدين Print و آخر شي تلاقي One page per sheet , اضغط عليها و اختار Two pages per sheet<br><br>​<span data-fid=\"stk-f1041513-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1041513-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1041513-0": {"name": "1.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/dc62af42e0722b9c1ff900f0ab62ffde2d4a99308ab03aeeaef28dc19468766f"}, "stk-f1041513-1": {"name": "2.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/3468935d9f8fdf0c5541311758372f8cbf1b3be3aa60ddf7a4217bee1504ff35"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me204/125994/1", "user": "S_H_A_D_O_W", "ts": 1337673234000, "tid": 125994, "pn": 1}}', 1337673234000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-turky_al-dossary-me204', 'stk-turky_al-dossary', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98182", "n": "Dr. Ahmet Ziyaettin Şahin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "~~~~ ME- 204 … Term: 121 ~~~~\n\nالتحضير :\n\nينادي بالاسماء اخر الكلاس ،، عادي تتاخر 🚬\n\nطريقة الشرح :\n\nيكتب في السبورة كم قانون وكم مثال ،، بس تفهم\n\nالكويزات :\n\nكويزاته متوسطه الى شوية صعوبه ،، يعطيك كلاس كامل ،، وبالعادة ما يسوي كويزات واجد ،، الى درجة سوى 4 كويزات وخذا افضل 2\n\nوفي 204 الكويزات عليها 20 ،، معناها كل كويز نص ميجر ،، فلا تضيعها\n\nالمياجر:\n\nكومن ،، وطالعين بسالفة “” نو فورميلا شيت “” 😞 ،، بس بو شاهين شنب قال جيبوا 👍 ،، بس ما اتوقع يسويها للسمسترات الجاية …\n\nالفاينلات :\n\nنفس نظام المياجر ،،\n\nالقريد النهائي:\n\nA 🌺\n\nالصوت :\n\nنازل نسبيا ،، بس واضح\n\nإضافات :\n\nمدرس تركي ،، مدرس في قمة الروعة ،، شرحه روقاااااااااان ،، ويعطيك الزبده ما يزعجك باشياء واجد ،، نوته حلو\n\nتصحيحة روعة وقريداته طيبه ،، اتمنى انه ينزل مواد لفل 4 ،، دايم يدرس ثيرمو ون وتو وسوي بحوث هذي شغلته\n___________________________________________\n\nاي سؤال ،، لا يردك الا رسالة خاصة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1162344-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ahmet-ziyaettin-sahin/98182/12", "user": "Turky_Al-Dossary", "ts": 1357926580000, "tid": 98182, "pn": 12}}]}', 1357926580000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4774-me204', 'stk-user4774', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me204\n\nالتحضير :\n\nينادي بالاسامي نهاية الكلاس\n\nطريقة الشرح :\n\nعنده سلايدات و يكتب نوت عالسبورة\n\nالكويزات :\n\nكوزاته صعبه بس يعطيك 4 كوزات وياخذ افضل 2 بس لا تتهاون فيها لان عليها 15% او 10% مو متاكد\n\nكالمياجر:كومون\n\nالفاينلات :كومون\n\nالقريد النهائي:\n\nB+\n\nالصوت:\n\nواطي بس واضح\n\nإضافات :\n\n- الدكتور يعطي امثله واقعيه\n\n- اعطانا البروجكت بدري فخلصناه بدري وما زحمنا قبل الفاينلاات\n\n- اذا يشرح حاجه جديده يسأل عنها اسئله تخليك تفكر فيها\n\n- السلايدات وافية وممتازة\n\n- نزلت الماده مع الدكتور بناء على كلام الشبااب الي فوقي وبصراحة كان الدكتور اقل مما توقعت بس مو يعني ان الدكتور سيء\n\n- انا ما عجبتني طريقة النوت بالرغم من انها ممتازه اذا حفظتها\n\n- اذا بتاخذ معاه 204 انتبه من الهوم وورك و الكوزات والبروجكت عليها تقريبا 35% والدكتور متساهل وزي ما قال اخوي يوسف الشاهين\n\nاصلاً ما تحس انك منزل مادة معه\n\nفتلاقي نفسك تسحب عليها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p890367-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/7", "user": "user4774", "ts": 1314052108000, "tid": 98189, "pn": 7}}]}', 1314052108000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5216-me204', 'stk-user5216', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بعد نهاية السمستر 111 مادة Me204\n\nالدكتور يصلح للـ سيلف ستدي\n\nالي يبغى الشرح لا ينزل معه !!\n\nوالي يبغى قريدات وتصحيييح عسسسل ينزل معه …\n\nالتحضير بالصوت وماعنده مشكله بالتاخير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970701-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/18", "user": "user5216", "ts": 1326927774000, "tid": 98189, "pn": 18}}]}', 1326927774000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amat_24-me204', 'stk-amat_24', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Semester: 111\nCourse: ME204\n\nالتحضير:\nيحضر بالاسم آخر الكلاس\nما يهمه متى دخلت ولا راح يسالك ليه تاخرت\nما راح يكلمك لو شاف غياباتك كثرت\nما يعطي DN، لاني استاهلها واظني غبت 12 مرة ولا كلمني او اعطاني شي\n\nالشرح:\nضعيف جدا، وما كنت القط معاه شي في الكلاس رغم اني في الصف الاول ودايما اكتب معاه…\nالكورس ما عرفت له لا من النوتس اللي اكتبها في الكلاس ولا من السلايدز ولا من الكتاب\n\nالـbonus:\nيعطي بونس احيانا على اسئلة غبية وسهلة جدا، اذا سال واحد منها اياك تضيعه\nبالذات اذا كنت مضيع في الكورس ولك اكثر من شهر ما فكيت الكتاب\nلانها صارتلي، كنت مو مذاكر شي من ايام الميجر وجبت بونسين في نفس اللكشر لانه الاسئلة كانت بسيطة عن الmass balance\n\nالبروجكت:\nجاء تااااافه مقارنة ببروجكت الشباب اللي ااخذينها عند مدرسين ثانيين\nكان فيه شغل بسيط coding على برنامج الEES\nاعطانا tutorial عليه بدل احد المحاضرات\nوطلب من الشباب اللي يخلصو الشغل بسرعة يساعدوه في الشرح لباقي الطلاب واعطاهم بونس عليها (وانا منهم 😆)\n\nميزة كبيرة له انه يعطي البروجكت بدري ويكون على جزئية ماهي في آخر المنهج\nكذا ما ينزنق الواحد مع باقي البروجكتات في نهاية السمستر\n\nالكوزات:\nعددها 4، ويحسبلك اعلى 2 بس\nما اقدر اعلق على صعوبتها او سهولتها ، لاني ما ذاكرت الا لواحد منها بس، وكان طويل بس سهل\n\nالاخلاق:\nجدا طيب وحبوب طوال السمستر\nلكن لا تقرب منه بعد نهاية الدراسة، يعني الفترة ما بعد المحاضرة الاخيرة الى الفاينل\nاخلاقه تتغير جدا، ويعلق ورقة على بابه: لو تبغى تناقشني في الكلاس وورك، لا تجي الا ومعاك كل كوزاتك وكل هومووركاتك وجامع درجاتك وحاسبها على ورقة، ولا خصم درجتين على طول\n\nقريدات الطلاب:\nاعطانا اكثر من حقنا ولله الحمد…\nالله يعطيه العافية\n\nاضافات:\nالدكتور للاسف هو الكوردنيتر لاسوء تقسيمة درجات شفتها في الجامعة\nمعقولة الكلاس وورك عليه 40% والمياجر عليها 30% بس؟!!!!!\nطيب ما دام عندكم نسب زيادة، ليه ما تزيدو للبروجكت بدل ما اعطيتوه 5% بس؟\n\nالقريد النهائي:\nC-", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972408-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/20", "user": "amat_24", "ts": 1327297897000, "tid": 98189, "pn": 20}}]}', 1327297897000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-stu2009-me204', 'stk-stu2009', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nME204,S122\n\nالتحضير :\nيحضر يوميا وينادي بالاسماء وبس عليك تقول يس\nطريقة الشرح :\nأول ما حضرت معاه كنت أكتب والصراحه الرجال شرحه سرييع جدا,لدرجة اني كنت أطلع من الكلاس ويدي تألمني من زود الأشياء اللي كتبتها,بعدها انضميت للشباب في التطنيش وبديت الحضور الجسدي…\nالكويزات :\nسوى لنا 3 والصراحه كويزاته متعبه نوعا ما وطويله,بس تصحيحه حلو\nالمياجر:\nالصراحه مياجر هالماده سهله والدكتور تصحيحه مثل العسل…بس تطنيشي للماده خلاني انصفع في ميجر تو(كلاس تست) وميجر 3\nالفاينلات :\nفاينل الماده طوو(طوووووويييييل)وويل\"أعتقد تكفي 🤠\" ويجيبوا فيه من كل شي بس مو صعب مره يعني الاسئله اللي على الشباتر اللي قبل الفاينل تجي سهله نوعا ما اما اللي بعد ماتيريال المياجر تجي أصعب شوي…\n\nالقريد النهائي:\nللدكتور A,مع اني لعبت في الماده بس طلعت بقريد طيب من عنده,ونصيحه لا تفوت البونص وحاول تتابع معاه في الكلاس اذا كنت ما بتكتب معاه وبتفهم…\nالصوت:\nواضح ويتكلم بنوع من السرعه\nإضافات :\nالدكتور طيب ومتعاون واخلاقه مثل العسل…وبالنسبه لتصحيحه فقط لا تخلي الورقه فاضيه وبيعطيك درجات 🤠…يعني لو توهقت في سؤال لا تخليه فاضي اكتب الحل اللي تتوقعه وبيعطيك عليه درجات 🤠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1229659-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/23", "user": "stu2009", "ts": 1369826427000, "tid": 98189, "pn": 23}}]}', 1369826427000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_111112-me204', 'stk-_111112', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204, Semester 161\n\nالتحضير : يحضر نهاية كل كلاس بالاسامي\nطريقة الشرح : يشرح الدرس على السبورة ويركز على المفاهيم >>>>الدكتور حتستفيد منه بخصوص ال,power plant cycles,refrigeration cycles, exergy\nموسوعة في العلم الله لا يضره\nالكويزات : اعطانا 3 كويزات الاول كان في بداية الترم والاثنين الباقية قبل نهاية الترم باسبوع\nالمياجر: كومون وتصحيحه لا يعلى عليه يعني تتوقع تاخذ 70 تلقاها 85 >>>يعطيك فوق حقك\nالفاينلات : كومون ونفس تصحيح المياجر\nالقريد النهائي: لو فيه فوق A+ عطيته\nالصوت: الصوت واطي شوي لكن خلك قدام عشان تسمع له بشكل افضل\nإضافات : الدكتور ذا حبيب من اسمه,اخلاق واسلوب في غاية الروعه+ حاول تجيه الاوفيس اذا في شي منت فاهمه\n\nالله يرضى عليك يا دكتور محمد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1468187-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/24", "user": "_111112", "ts": 1486971402000, "tid": 98189, "pn": 24}}]}', 1486971402000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kfupmer2014-me204', 'stk-kfupmer2014', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204, Semester 171\n\nالتحضير : يحضر نهاية كل كلاس بالاسامي\nطريقة الشرح : يشرح الدرس على السبورة ويركز على المفاهيم >>>>الدكتور حتستفيد منه بخصوص ال,power plant cycles,refrigeration cycles, exergy\nشرحه مش بطال وجيد\nموسوعة في العلم الله لا يضره\nالكويزات : اعطانا 3 كويزات واخذ افضل اثنين\nالمياجر: كومون وتصحيحه خرافي بمعنى الكللممةة\nالفاينلات : كومون ونفس تصحيح المياجر\nالقريد النهائي: لو فيه فوق A+ عطيته\nالصوت: الصوت واطي شوي ولهجته مصرية ويجيب النوم\nإضافات : الدكتور ذا حبيب من اسمه,اخلاق واسلوب في غاية الروعه\n\nتعاملة يذكرني بأبوي بطيبته واخلاقه والاسلوب الفكاهي الي يطرحه من وقت الى اخر\n\nطبعا انا سجلت عند الفرايضي لكن حطوني عنده بدال الفرايضي والحمدلله\n\nدكتور اسطوري الله يوفقه دنيا واخره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485921-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/25", "user": "KFUPMer2014", "ts": 1515599279000, "tid": 98189, "pn": 25}}]}', 1515599279000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-illusions-me204', 'stk-illusions', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204\nTERM 181\n\nالتحضير : نهاية الكلاس وجدا جدا متساعد بالتأخير لدرجة ان الشعب بدوا يمصخونها ويحضرون بعد ثلث ساعه , بس على اخر شهر صار يدخل ولا يلقى الا اربعه خمسه فحضر يمكن مرتين ولا ثلاث ببداية الكلاس وحط الباقين كلهم ليت وكان متضايق من اللعب الي حاصل لانه زاد عن حده.\n\nطريقة الشرح : عنده سلايداته , بكل بساطة كان يفتحها بعدين يكتب القوانين حقت السايكل ويتكلم عنها ويحل ممكن سؤال اول سؤالين عليها , انا اول شهر كنت احاول انتبه بس صوته نبرة وحده فكان يجيني النوم ولا صرت اركز للامانة فما ادري.\n\nالكويزات : عطانا 3 كويزات ولا رفع السلوشن حقهم وللامانة مب سهلين , واحد قبل الميجر الاول واثنين اخر اسبوع بالمسمتر واخذ اعلى اثنين (عليهم 15 درجة من مية) فكثير مره\n\nالمياجر: كومن , كانت مياجرنا كل سؤال مقسم حول 5 فقرات وكل فقرة عليها تقريبا 3 درجات فما كان يقدر يدف مرة اصلا فاشوف انه يعطي فوق حقك بشي بسيط مب زي ما قالوا الشباب فوق انه مره يدفك.\n\nالفاينلات : كومن ولا شفنا درجته\n\nالقريد النهائي للدكتور: B+\n\nالصوت: نبرة وحدة بس واضح ولهجته واضحة.\n\nإضافات :\n-الدكتور هذا حرفيا له من اسمه نصيب صدق انه حبيب , حتى لو انك جاي متأخر ولا مب منتبه مره وسألته بتلقاه يجاوبك بصدر رحب , كان متساعد معنا من ناحية تسليم الهومووركات وكنا اذا كلمناه اخره يومين على طول فأجل لنا وقت تسليم يمكن ثلاث هومووركات\n\n-البروجكت حقه بسيط وعنده كلاس ياخذنا فيه لواحد من اللابات ويسوي الكود قدامك ويقول لك يالله سوه وخلصه الحين بالخمسين دقيقة , والي يخلص يسجل اسمه ويساعد اخوياه فتمر الخمسين دقيقة وكل الكلاس يصيرون مخلصين الكود حق البروجكت والرسمة الي هم اغث شغلتين بالبروجكت بمساعدته , وكان يقول لازم تسلموني اياهم الحين لانهم هم اصعب شغلتين ممكن تواجهكم بالبروجكت ولا الباقي ريبورت تسويه وخلصنا, فالبروجكت عنده سهااالات مرة وزيادة على كل هالمساعدة أجل لنا تسليمه اسبوع .\n\n-كان يسأل اسئلة بسيطة مرة ويعطي عليها بونص كل كم كلاس سؤال ولا سؤالين , مثلا يقول لك وش الاكويجن حق الوورك ان عند البمب هنا ؟ لو انك شايف رسمة السايكل ممكن تجاوب , فلو تقرا قوانين السايكل قبل الكلاس بالغالب بتاخذ اكثر من بونص عنده.\n\n-الغيابات كان قايل لنا لكم 3 غيابات مسامحين فيهم ويوم جاء اخر يوم بالسمستر قال لنا بحذف 5 مب 3\n\n-ما ادري كم جبت بالفاينل بس القريد الي اعطاني اياه احسن من الي كنت اتوقعه الله يجزاه خير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504167-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/27", "user": "ILLUSIONS", "ts": 1545956012000, "tid": 98189, "pn": 27}}]}', 1545956012000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-me204', 'stk-khdsa2022', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98190", "n": "Dr. Syed Said", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATS APP\nاسم الدكتور : سيد سعيد\nالمادة: me 204\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يحضر اوقات و اوقات ولا في خصم ع التحضير\nطريقة الشرح : شرييييييح\nالكويزات : يوزع اوراق عمل ويجيب منهم او نفس الطريقه وكذلك يجي منهم ف المياجر بنفس الاسلوب\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: A\nالصوت: واضح ، يشرح عربي وأوقات انجليزي\nإضافات :", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518802-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-said/98190/9", "user": "Khdsa2022", "ts": 1578287439000, "tid": 98190, "pn": 9}}, {"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "by whatsapp\nسم الدكتور : محمد حبيب\nالمادة: me 204\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\nاخلاق عاليه جدا شرحه ممتاز الى ابعد حد خصوصا في السايكلز ويربطها دايم في الحياه الواقعيه وايضا كان شرحه في ال reaction فنان لكن بالنسبه ال exergy و ال air conditioning ماكنت مركز معه ولا اتوقع انه شرحه زي ما شرح السايكلز\nالتحضير : اول الكلاس بعدين ليت\nطريقة الشرح : سلايدات واضحه ومسائل يحلها ع السبوره\nالكويزات : ٣ كوزات ياخذ افضل ٢\nالمياجر: يهتم بالطريقه فاذا الطريقه صح والناتج غلط م يخصم واجد\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : يعطي انشطه عليها بونص وممتعه لا تفوتها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518805-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/28", "user": "Khdsa2022", "ts": 1578288072000, "tid": 98189, "pn": 28}}]}', 1578287439000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yazeed_alshehri-me204', 'stk-yazeed_alshehri', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204 - 192\n\nوالله من افضل الدكاترة اللي درست عندهم في الجامعة اخلاقا\n\nنص الكورس حضوري والاخر عن بعد بسبب كورونا\nيحضر اخر الكلاس\nكويزاته : متوسطة\nالكورس هذا عبارة عن نزل عند افضل دكتور يعطي درجات والمذاكرة من مقاطع محمد شايع القحطاني ع اليوتيوب\nالبروجكت عطانا كل شيء نحتاجه من عمليات ورسم بس اللي عليك تمليه كلام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525796-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/29", "user": "Yazeed_Alshehri", "ts": 1600610032000, "tid": 98189, "pn": 29}}]}', 1600610032000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-trad-me204', 'stk-trad', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98189", "n": "Dr. Mohamed Habib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204-202\n(Online)\n\nالتحضير :\nيحضراخر الكلاس\n\nطريقة الشرح :\nيستخدم سلايداته وشرحه جيد بس ما كنت اعتمد عليه كنت اعتمد على شرح القحطاني\n\nالكويزات :\nيعطيك ثلاث كويزات متوسطة الصعوبة وياخذ افضل اثنين. الطريقة ذي اشوفها مزعجة نوعا ما لان الكويز الواحد وزنه عالي كان تقريبا 8 بالمية عالكويز الواحد فنصيحة لاحد يجيب العيد فيها.\n\nالمياجر: ميدتيرم وهو اللي سواه وكان متوسط الى صعب شوي واعتقد انه مايغير الاسالة ممكن بس يغير الارقام فاذا طحت على اختباراته القديمة فرصة.\nالفاينلات :هو اللي سواه وكان صعب والله كان متروس فقرات لين خشمك السوال الواحد فيه ثلاثة اسالة.\n\nالقريد النهائي:ِ+A\n\nالصوت: واضح ومفهوم\n\nإضافات :\nالدكتور اسم على مسمى ومتعاون مع الطلاب بشكل كبير من ناحية الشرح وتاجيل الكويزات والواجابات . تصحيحة ممتاز واذكر اني جيت ناقشت معه الميدتيرم وكان فيه اشياء غلطان فيها هو وزودني تقريبا 7 درجات. يكرف شوي الصراحة من ناحية الاسيمنتات واحيانا يطلب منك اشياء مثل مقاطع وشروحات ويعطيك بونص عليها. انصح فيه وبشدة اذا لقيته لا تفوته.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530040-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-habib/98189/30", "user": "Trad", "ts": 1621641064000, "tid": 98189, "pn": 30}}]}', 1621641064000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-madridista-me204', 'stk-madridista', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98190", "n": "Dr. Syed Said", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "171 - ME204\n\nالتحضير : تحضير يومي لكن بعض المرات مايحضر\nطريقة الشرح : شرحه رهيب ويوصلك المعلومة 100% … طريقة شرحه انه يخلي كلاس حق الشرح، وبعدها في كل مرة يوزع ورقتين فيها اسئلة ويخلينا نحلها… في نهاية الكلاس يعلمنا كيف طريقة حلها\nالكويزات : كويزاته نفس الاسئلة اللي يوزعها بالكلاس… نفس الأفكار، ذاكرها كويس وبتجيب درجات حلوة فيها\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: واضح\nإضافات :\n\nالدكتور مشكلته انه يتعبك … يعني تقريباً في كل اسبوع كويز او كلاس تست، غير ان المادة اساساً تطلب منك هوموورك كل اسبوع …\nشرحه ممتاز ويحل بالسبورة ويرحب بالأسئلة ويهتم جداً بفهم الطلاب ,\nعنده مشكلة ثانية هي جملته الشهيرة \" no discussion الله يجزيك خير\" … يعني يحدد وقت كويز او كلاس تست خلاص لا تحاول تناقشه نهائياً لان مستحيل يغير رأيه (راسه يابس)\nبالنسبة للقريدات للحين ماعطانا اياها… لي عودة بعد مايعطينا اياها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485817-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-said/98190/6", "user": "Madridista", "ts": 1515502467000, "tid": 98190, "pn": 6}}]}', 1515502467000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-owheading-me204', 'stk-owheading', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f118647", "n": "Dr. Bilal Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204 term 172\nالتحضير : -\nطريقة الشرح : من السلايدات فقط، سيئة وما يهتم بفهم الطلاب\nالكويزات : MCQs، نوعًا ما فيها صعوبة\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: -\nالصوت: سيء ولهجته مو ذاك الزود\nإضافات :\nما كملت معاه الترم، فماعرف كيف تصحيحه…\nلكن الدكتور كان شرحه سيء فعلًا، وما يكتب شيء ع السبورة إلا نادرًا، والمادة تحتاج شريح وشخص يعبي السبورة كل يوم\nما انصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509013-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bilal-qureshi/118647/6", "user": "OWHEADING", "ts": 1556275457000, "tid": 118647, "pn": 6}}, {"id": "stk-dr-f98190", "n": "Dr. Syed Said", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204 TERM 181\nالتحضير : بالأسماء\nطريقة الشرح : غالبًا ع السبورة وقليل من السلايدات\nالكويزات : كتابية\nالمياجر: كتابية و موحدة\nالفاينلات : كتابية وMCQs\nالقريد النهائي: A+\nالصوت: لهجة الدكتور بتحسها غريبة شوي في البداية لكن بتتعود عليها بسرعة\nإضافات :\nإيييه يادكتور سعيد، الله يسعدك دنيا وآخرة، يهتم في الطلاب كأنهم أولاده، يعيد ويزيد في الشرح ويتقبل كل الأسئلة، يعطيك أسئلة اختبارات سابقة عشان يعودك عليها ويحلها في الكلاس، وما يقصر معاك من ناحية التصحيح والدرجات وجدًا متعاون\nمن أفضل الدكاترة الي درسوني في حياتي صراحة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509015-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-said/98190/7", "user": "OWHEADING", "ts": 1556275659000, "tid": 98190, "pn": 7}}]}', 1556275457000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-me204', 'stk-guest', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98190", "n": "Dr. Syed Said", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 204\nterm 201 اونلاين\nالتحضير : يحضر ثلاث الى اربع مرات كل كلاس بوقت عشوائي عن طريف فورم يسويه في تيميز\nطريقة الشرح : سلايدات و يشرح و يستخدم الباور بوينت في الكتابه ف خذ لك انواع الخط التعبان و الشخبطه و ما يمديك تدري شصاير\nالكويزات : بشكل عشوائي ، عطانا تقريباً ٦ كوزات عليهم حول ٣٠ و برزنتيشن و تيك هوم كوز\nالمياجر: كل دكتور لحاله ، كان مستواه طبيعي\nالفاينلات : حرقنااااااااااااا حررررررررررق\nالقريد النهائي: F\nالصوت: واضح\nإضافات : الدكتور اخلاقه زينه ، بس عشت معاه اقوى انواع الضياع و العشوائيه ، الكوز ما تدري كم عليه الوقت ما تدري عنه ، ما تدري شلون صحح لك ، القريد نزله على طول في البورتال ، ما ندري كم جبنا في الكلاس ورك و ما ندري كم جبنا في الفاينل ، جاب فاينل غريب عجيب ، انا عن نفسي اشوف ان انا ظُلمت في كذا الكورس ، الدكتور ما ينفع اونلاين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527650-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-said/98190/10", "user": "Guest", "ts": 1609929920000, "tid": 98190, "pn": 10}}, {"id": "stk-dr-f182519", "n": "Dr. Awad Alquaity", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me204 - T211\n\nالتحضير:\nفي بداية الترم ما كان يحضر ويفكر في طريقة للتحضير بعدين خلاها ورقة تمر على الطلاب\n\nطريقة الشرح:\nيشرح من السلايدات ويعقب على كل سلايدة. بالنسبة لي شوي ما ارتحت لشرحه لأنه يتكلم بسرعة واللهجة لازم تتعود عليها، واذا تعودت على سرعته واللهجة بيكون شرحه مفهوم وواضح.\nأفضل شيء في سلايدات الدكتور الاسئلة اللي فيها أغلبها تكون في مستوى المياجر ويشرحها الدكتور في الكلاس خطوة خطوة.\n\nالكويزات:\nالدكتور عنده نظام Pop quizzes و Quizzes عادية، البوب كويز كانوا خمسة وعليهم 2% وكانوا عن طريق البلاكبورد ولك محاولات لا نهائية بس في خمس دقايق وسهل جدا تجيب فل مارك فيهم حتى لو ما ذاكرت. الكويزات العادية اخذنا تقريبًا خمس كويزات وكانوا MCQ و رتن وكلهم سهلة جدًا.\n\nالمياجر:\nكومن\n\nالفاينلات:\nكومن\n\nالقريد النهائي:\nA+++ بدون منازع وبالنسبة لي اشوفه افضل دكتور يدرس الثيرمو\n\nإضافات :\nالدكتور متساهل فالتصحيح بشكل خيالي لدرجة افرج المياجر يوصل حدود 73% وللأسف انها بتأدي لارتفاع القريدات لرينج تحت الستاندرد بشوي. اتوقع في سمسترنا كانت الـ A+ من 92-93، فأحرص انك ما تضيع المياجر وتتساهل فيهم. الدكتور متعاون بشكل خيالي لو بغيته في أي شيء بيساعدك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533393-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/awad-alquaity/182519/4", "user": "Guest", "ts": 1641843563000, "tid": 182519, "pn": 4}}]}', 1609929920000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3804-me204', 'stk-user3804', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98193", "n": "Dr. Syed Zubair", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204 قبل ماتصير كومون\n\nالتحضير :\n\nكان عددنا قليل فالظاهر حفظنا :d\nفما أقدر أحكم انه كان يحضر يوميا ولا لا, لأني ماكنت اشوفه يحط علامة\nفي ورقة التحضير للي يغيبون\n\nطريقة الشرح :\n\nللأسف كان يشرح لنا عن طريق السلايدات ونادراً ماكان يستخدم الصبورة\nلأنه كان يبغى يخلينا نفهم الكونسبت مضبوط\nبس المشكلة ماكان يحل الأمثلة ولاشي\nيفتح السؤال و يورينا السليوشن بالبروجكتر ويسويله هايلايت\nيعني ماتقدر تتبع معه بالكتابة أو بالصبورة إلا اذا استخدمها وهو نادراً\n\nالصراحة طريقة شرحه ماجازت لي…\n\nالكويزات :\n\nمتوسطة, بس تصحيحه حليو\n\nالمياجر:\n\nمتوسطة\n\nالفاينلات :\n\nمتوسطة\n\nالقريد النهائي:\n\nB\n\nالصوت:\n\nعالي بس اللهجة شوي يبيلك تتعود عليها في أول اسبوع\n\nإضافات :\n\nما أدري اذا غير أسلوبه ولا لا, لأني يوم اخذ 204 الظاهر كانت في 2008", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p789654-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-zubair/98193/3", "user": "user3804", "ts": 1297680315000, "tid": 98193, "pn": 3}}]}', 1297680315000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8551-me204', 'stk-user8551', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98193", "n": "Dr. Syed Zubair", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204 - Term 122\nالدكتور هندي ، تخصصه في مواضيع الـ Heat Exchange\n\nالتحضير : كل محاضرة ببداية الكلاس ، ينادي بالإسم و يحضر على ورقة ، يحضر المتأخرين بعد المحاضرة و ما يسجل عليهم تأخير.\nما أعتقد إنه يخصم عالغياب بنهاية الترم ، إن كنت بتغيب عن كلاس أرسل له إيميل أو علمه الكلاس اللي قبله عشان ما يسجل عليك غياب.\n\nالشرح : بصراحة أشوفه من أفضل الدكاترة اللي درست عندهم من ناحية الشرح ، يشرح من سلايدات و يستخدم السبورة ، نادر ما يحل مسائل و إذا بغى يحل يفتح السلوشن مانوال عالبروجكتر و يشرح عليه.\nأكثر نقطة أعجبتني فيه هي “الإستطراد” ، يعني يعطيك معلومات حلوة تفيدك كمهندس ميكانيكي.\n* درست مع السرخي ثيرمو 1 و مع زبير ثيرمو 2 ، و بصراحة حبيت الثيرمو و فهمتها بشكل أكبر م زبير.\n\nالكويزات : مثل ما قال عبدالله ، أول كويز صعب و الباقي سهالات ، أعطانا 4 كويزات و أخذ أفضل ثلاثة.\nأفرج الكويز الأول = 4\nأفرج الكويز الثاني = 7\nأفرج الكويز الثالث = 6 (تقريبا)\n\nالتصحيح : إذا جوابك النهائي خطأ يشوف خطواتك و يعطيك قريد عليها ، تصحيحه بالنسبة لي كان ممتاز لكن ما أدري ليه الأفرج عنده دايما طايح و بعنف !\nمن تجربة ، ترتيبك للحل (خط واضح و ما فيه شخابيط كثير) يؤثر على قريدك.\n\nالقريدات : الفاينل عندنا كان ليلة الأحد ، ظهرية الأحد طلع الفاينل قريد!\nبإختصار ، إذا كان الدكتور يعرفك بالكلاس و دايم تشارك معه فأبشر بالقريد اللي يشق الوجه 😁 ، أعطاني أكثر من حقي.\n\nالصوت : واضح ؛ لكنه دايم يقول (ها) و هو يتكلم << بتتعود عليها 🤠.\n\nإضافات :\n- الرجال خدم بالسعودية لفترة طويلة و عنده خبرة بمناطقها و مصانعها ، فدايما يجيب أمثلة واقعية.\n- يحقد على اللي يستخدم جواله بالكلاس.\n- يقدر الطالب اللي يكتب نوت معه ، و يوصي كثير على كتابة النقاط المهمة اللي يقولها.\n- أخلاقه وسط ، مهيب زينة و لا شينة.\n- لو تسلم الهوموورك بعد تاريخه بيوم ، يقبله.\n- أعطانا بروجكت طويل لكن راعانا بالتصحيح.\n- يهتم ببرنامج الـ EES ، سلوشن الكويزات/المياجر ينزلها بالويب سيتي بصيغة EES … أخذ كلاس كامل يشرح فيه هذا البرنامج “باللابات”.\n\nدرست معه الـ 204 ، و ناوي انزل معه الـ 315 و كورس إلكتف بعد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1244210-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-zubair/98193/24", "user": "user8551", "ts": 1373402924000, "tid": 98193, "pn": 24}}]}', 1373402924000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ksa1990-me204', 'stk-ksa1990', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98193", "n": "Dr. Syed Zubair", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204 - T172\nالتحضير :\nبداية الكلاس والي يجون متأخر يحضرم نهاية الكلاس خصم نص درجة على كل غياب ما أتوقع انه يحط ليت يا حاضر يا غايب\nطريقة الشرح :\nأسوء شرح في الحياة يدرسنا ثيرمو ونادر يستخدم السبورة وما يحل مسائل يفتح المسائل من المانيوال ويتكلم عنها على السريع وخلاص!! ونادر يفتحها بعد غالبا يقرا الامور الي فيها كونسبت من الباوربوينت من الاخر شرحه غير مفيد ابدا والي يقهر اكثر لا يشرح زي العالم والناس ولا يخليك تقعد على الجوال.\nالكويزات :\nالكوزات جحفلنا أكثر من مرة يحدد متيريال ويجيب من ماتيريال ثاني ودائما كوزاته فيها فكرة غريبه وصعبة\nواذا جاب سؤال سهل لازم يحط فيه تريك قبل اذا عرفته بعدين ينحل السؤال\nالمياجر:\nتصحيحه عادي ما يدف ولا يظلم يعطيك حقك\nالفاينلات :\nنفس المياجر\nالقريد النهائي:\nD+\nالصوت:\nاللكنة الي يتكلم فيها مو مرة واضحه وكل شوي يقول ها … ها يمكن يعيدها كل كلاس حول 10 مرات\nإضافات :\nتسجيلي عنده كان غلطة ومستحيل تتكرر مرة ثانية\nالثيرمو 2 معروفه فيها قوانين وكثير وسايكلز كثيرة وجدا صعب انها تنحفظ ومعروف عن المادة ان الطالب يكتب القوانين الي يبيها ويدخلها معاه بالاختبار\nوسيد زبير للأسف صار الكوردينيتر في 172 ولغا نظام انك تدخل فورميلا شيت وعطانا فورميلا فاضية ما فيها الا كم قانون ما منها فايدة وقال الساكلز لازم تحفظونها كلها وهي مرة كثيرة وحفظها جدا صعب وفي الكوزات ما يعطيك اي فورميلا ولا يكتبلك اي قانون يقول لازم تجي حافظ كل شيء من قوانين وساكلز\nبعد هذا كله هذا اسوء دكتور مر علي بقسم الميكانيكا كامل\nيوم شفت سكاشنه حقت 181 مقفلة قلت لازم اعطيكم خبرعلشان ما تنتكبون فيه فالي عنده فرصة يغير الدكتور لا يتردد انحش بجلدك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1490357-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-zubair/98193/28", "user": "ksa1990", "ts": 1522871899000, "tid": 98193, "pn": 28}}]}', 1522871899000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8053-me204', 'stk-user8053', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98195", "n": "Dr. Abdulghani Al-Farayedhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204\n\nالتحضير :\nيومي ومهتم جداً في التحضير كما هي العادة عند كل الدكاترة السعوديين الكبار\nطريقة الشرح :\nيكتب نوت ممتاز ويغني عن الكتاب\nالكويزات :\nتكون عادة في الليل ومن الاولد اكزام نصاً بالارقام\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي: b+\nالصوت: واضح ولغتة جيدة\nإضافات :\nلا تستغرب انك تأخذ معه قريد أقل من الي انت متوقعه بكثيير !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049166-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulghani-al-farayedhi/98195/9", "user": "user8053", "ts": 1338591896000, "tid": 98195, "pn": 9}}]}', 1338591896000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatif1994-me204', 'stk-abdullatif1994', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98195", "n": "Dr. Abdulghani Al-Farayedhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: Me204\nالترم: 141\nالتحضير : التحضير نهاية الكلاس او بدايته … طبعا شبه يومي\nطريقة الشرح : عنده نوت يمشي عليها … طبعا اما تفهم معاه او تكتب معاه … لان ماراح تلحق على الاثنين\nالكويزات : مافيه كويزاته … كان يعطينا كلاس تست 2 …\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C+\nالصوت: صوته واضح\nإضافات : الدكتور مشكلته انه سريع في الكتابه وهم سريع في المنهج … يعني بعض احيان يسبق البقيه …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1425776-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulghani-al-farayedhi/98195/22", "user": "Abdullatif1994", "ts": 1440563532000, "tid": 98195, "pn": 22}}]}', 1440563532000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9213-me204', 'stk-user9213', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98195", "n": "Dr. Abdulghani Al-Farayedhi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204 - Term 152\n\nالتحضير : بشكل دائم و بعض الأحيان يكون تعبان فيكنسل. يسمح بالحضور بالسكشن الثاني و كل غياب عليه خصم .\nطريقة الشرح : نوت ممتاز جدا جدا بس عيبه الأرقام فيها أخطاء حسابية يعني لا تعتمد عالمكتوب أحسبها بنفسك و يكتب بشكل سريع عشان كذا اذا منت من النوع السريع مره فالكتابة أو ما تعرف تركز و تكتب بنفس الوقت خذ نوت لزميل درس معه أو حق الجمعية ( مو واضح و ناقص بالأخير)\nالكويزات : no quizzes Only two class tests before every major exam .\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+++\nالصوت: واضح جدا\nإضافات : المدرس حبوب و أخلاق و يعاملك كمهندس مو طالب و أخلاقه عالية و متسامح كثير . مياجرنا كانت اصعب من الاترام السابقة بمراحل لأن الماتيريال يختلف و الكوردنيتر جديد بس مشت الأمور, لأن الدكتور الفرائضي ما شفت أحد يصحح زيه أبدا ! أذا الطريقة صح راح تنقص بالكثير 1 بوينت من سؤال عليه 30 بوينت .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452942-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulghani-al-farayedhi/98195/28", "user": "user9213", "ts": 1467277646000, "tid": 98195, "pn": 28}}]}', 1467277646000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11518-me204', 'stk-user11518', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98197", "n": "Dr. Shahzada Shuja", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204-191\n\nالدكتور شجاع صراحة شريح درجة أولى ومن أفضل الدكاترة اللي درست عندهم\n\nالتحضير عنده قبل يبدأ الكلاس بكم دقيقة وممكن يعطيك دقيقة أو دقيقتين زيادة وبعدها ليت ، على حسب مزاجه\n\nالكورس الكونسبت فيه كثير وممل مرات يكون ، الحلو ف الدكتور انه مرات يعطيك الكونسبت عن طريق قصص ، يعني مثلا ليش ابتكروا مكينة الديزل ووش فوايدها ومميزاتها عن مكينة البنزين ، واشوف هذي من الاشياء اللي تميزه\n\nبيعلمك على برنامج ees وممكن يخلي كم هومورك اجباري تحلونه فيه ، والافضل انك تتعلم عليه لان البروجكت بيكون فيه\n\nالكويزات اختبرنا كويز واحد بس وبعدين صرنا ندرس عن بعد ، تصحيحه ف الميجر بطل لدرجة ان افرج سكشننا كان 80 وشي ، ويوم رحت اشوف ورقتي اكتشفت ان عندي اغلاط كثيرة بس كان يحاسب على الفهم\nبرضو إيجابية في الدكتور شجاع أن تصحيحه سريع جدا للميجر والكويزات ، الميجر اختبرناه ف الليل ونزله ف نفس الليلة للسكشنين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522030-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shahzada-shuja/98197/11", "user": "user11518", "ts": 1589456231000, "tid": 98197, "pn": 11}}]}', 1589456231000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11264-me204', 'stk-user11264', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98197", "n": "Dr. Shahzada Shuja", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204 - 192\nالتحضير: بالأسماء قبل المحاضرة حتى دقيقتين من بدئها وبعدها ليت\nطريقة الشرح: يفتح سلايداته ويشرح ويكتب على السبورة كثير، والمسائل اللي يحلها هي مسائل الهوموورك، وشرحه ممتاز… في وسط الترم صار يحل الأسئلة بشرح الأفكار بس وكتابة القوانين وما يحلها حل كامل ولا يعوض بالأرقام\nالكويزات: كويز واحد كان صعب شوي والافرج نازل بعدها حولنا أونلاين\nالمياجر: كومن، وتصحيحه سرييييع جدًا اختبرنا الساعة 8 ونزل الدرجات الساعة 1 الليل! والافرج كان عالي بعد (حول الثمانين)\n\nإضافات:\n- الدكتور بيعلّمكم على برنامج EES والبروجكت النهائي حق المادة راح يكون منّه\n- ممكن تستخدمون البرنامج في حل الهومووركات، حنا قال بكيفكم تبون تحلونه يدوي أو بالبرنامج، واللي يسوي الاثنين له بونص على مجموعه النهائي … وأشوفها حركة جميلة للأمانة\n- الدكتور كان متعاون معنا صراحة وإذا طلبناه تأجيل أحيانًا يرضى وأحيانًا يرفض، فواضح أنه مزاجي. وعيبه أيضًا أنه سحبة ومب دايمًا يرد على الإيميلات\n- أنصح فيه ولا لا؟ والله مدري ما كنت مرتاح معه هههههههههههههه… لكن من نظرة حيادية تراه كويس لكن لازم تشتغل وتكون مذاكر أول بأول وتكون مذاكر لكويزاته كأنك مذاكر لميجر لأنها صعبة ولها نسبة كبيرة في المجموع النهائي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522264-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shahzada-shuja/98197/12", "user": "user11264", "ts": 1590183000000, "tid": 98197, "pn": 12}}]}', 1590183000000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-j7oof-me204', 'stk-j7oof', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 192 \"ترم الكورونا \" … مادة me204\nالتحضير :- ما فيه تحضير وحضور الكلاسات اختياري\nالواجبات ملغية وتعويض درجاتها بكلاس تيست\n\nالشرح:- قناته في اليوتيوب مرجع عظيم لكل طلاب المادة … شرح اسطوري يدخلك بأجواء التخصص وتحس نفسك مهندس جد … مهما قلت ما اقدر اوفي حقه في الشرح\nاضافات:-\nالدكتور من بعد ازمة كورونا وهو يفصل علينا كثير! كلاس تيست وقته المعقول ساعه ونص يعطينا 40 دقيقة يقول عشان ما تغشوا… وكان الوضع معنا تهديد ووعيد\nلكن بالنهاية الدكتور يبي مصلحة الطلاب وهالشيء ما يختلف عليه عاقلين … انصح بالتسجيل عنده للي وده يستمتع فعلًا بالتخصص\n\nتقييمي له A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521674-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/38", "user": "J7ooF", "ts": 1588237733000, "tid": 98200, "pn": 38}}]}', 1588237733000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wil.e-me204', 'stk-wil.e', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "191 - ME204\n\nالتقييم متاخر لكن تقييمي مبني على كلام الشباب اللي قبل،\n\n1- باختصار شديد ومفيد الدكتور عسل مع المجتهدين، ما ادري اذا غير نظامه ولا لسا موجود لكن كان يقول للشباب اللي ماوده يجي لا يجي، فمن ناحية التحضير كان يسمح لنا ما نجي بشرط نكون مغطين المادة من مقاطع الفيديو اللي اشوف انها كافية الصراحة للمذاكرة، متساهل ومتساعد مع المجتهدين في مسالة البونص مع اللي يستاهلون فكون اني كنت احضر معه السمستر كامل في كلاس الساعة 1 الظهر كان شايف هالشي مني ومن ال4 اللي كانو يحضرون معي فكان جدا متعاون بهالشي.\n\n2- المادة بسيطة للي يتابعون معه بالكلاس ويتابعون مقاطعه، ويحترم اللي يدعون له ويثنون على مجهوده ( قناته جبارة ماشاءالله عليه ) والقناة تعتبر مصدر ممتاز للمذاكرة فلا تفرطون فيها\n\n3- ابدا لا تحضر اي اختبار او اي كلاس له بشورت لانه يتضايق منه ويمكن يطردك بسببه\n\n4- بشكل عام مفضل للمجتهدين وقليلين الغياب والحريصين على محتوى المادة، اسلوبه ممتاز وشرحه واضح يعاب عليه المزاجية لكن بيني وبينكم بعض الطلاب ما يمشون الا بالعين الحمرا لكن طول ما انت ممتاز معه بيكون ممتاز معك\n\nبشكل عام الدكتور اشوفه A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534535-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/45", "user": "wil.e", "ts": 1654152323000, "tid": 98200, "pn": 45}}]}', 1654152323000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7794-me204', 'stk-user7794', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98201", "n": "Dr. Haitham Ba-Haidarah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أول شيء… آسف لو جاء هذا الرد متأخر …يعني بعضكم يمكن قد سجل… 😊\n\nأنا ماخذ معه الحين ME204 ترم 141\n\nطبعاً التقييم بيكون الى اللحظة ذي و بنهاية الكورس بكمل الباقي 🙂\n\nالتحضير :\nبداية الكلاس …دائماً و أبداً\nيحضر بالأسماء مرتين و بعدها يبدأ الدرس و و يحضر الباقي Late نهاية الكلاس\n\nطريقة الشرح :\nشرحة سلس و يشرح كل شيء خطوة بخطوة بطريقة غير مملة و كمان تخليك تفهم الكونسبت 👍\nطبعا الكلام ذا للـ cycles\nو بعدها تقلب المادة ماث 😐 يعني Equisions و Relations و حاجات يبيلها سيلف ستدي لأنه صعب يشرحها …\n\nالكويزات :\nالى الحين ما عطانا كلاس تست … و بدلها ب كويزات و عليها درجة الكلاس تست 20%\nو بصراحة أشوف انه أفضل من الكلاس تست لأن المتيريال بيكون أقل و كمان لو جبت العيد يضل كويز 🙂\nطبعاً كل نهاية تشابتر كويز …\nمستوى صعوبتها سهل الى متوسط أو بالأصح لو حال الهوموورك بنفسك رح تكون سهلة 👍\n\nالمياجر:\nكومن\nو تصحيحه نوعا ما شديد\n\nالفاينلات :\nNot Yet\n\nالقريد النهائي:\nNot Yet\n\nالصوت:\nواضح جدا\n\nإضافات :\n\nفي بداية الكورس 204 … عمل لنا مراجعه لـ 203\nو صراحة فهمت معه أشياء كثير ما فهمتها من السرخي\nبشكل عام أنصح به\nكل التوفيق 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1417267-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/haitham-ba-haidarah/98201/4", "user": "user7794", "ts": 1417549771000, "tid": 98201, "pn": 4}}]}', 1417549771000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8624-me204', 'stk-user8624', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98201", "n": "Dr. Haitham Ba-Haidarah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME204 TERM 141\n\nالتحضير :\n\nشدييد جدا في التحضير … يحضر في اول دقيقة وبعد كذا late\n\nطريقة الشرح :\n\nيشرح من لسلايدات اللي في موقعه … شرحه ممتااااااااااز جدا جدا جدا , والجميل إنه يراجع لك الدرس اللي فات في اول ربع ساعة … ويحل مسائل من الكتاب موجودة في سلايداته\n\nالكويزات :\n\nيعطي تقريبا 5 الى 7 كوزات … كل كوز 3 درجات مجموع درجات الكوزات 20% -- ما يعطي كلاس تست\nوما أعطانا بروجكت …\n\nالمياجر :\n\nمائله للصعوبة …\nوالوقت قصيير\n\nالفاينل :\nكان متوسط والوقت المتاح جيد بالنسبة لمستوى الأسئلة\n\nالقريد النهائي:\na+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420658-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/haitham-ba-haidarah/98201/6", "user": "user8624", "ts": 1421690936000, "tid": 98201, "pn": 6}}]}', 1421690936000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-me204', 'stk-m_nd_m', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98201", "n": "Dr. Haitham Ba-Haidarah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T162 - ME204\n\nالتحضير : ينادي الأسماء بداية الكلاس… اذا كانت الساعة صارت 8 (بداية الكلاس) و مر على اسمك و انت ما رديت خلاص أعتبر نفسك لييت… يعني من الآخر شديد جدًا جدًا جدًا بالتحضير و مايحذف ولا غياب ولا لييت لكن للأمانة أيانة المطر القوي تعاون معنا و برضو اليوم اللي بعد الميجر عادًة ما يحضر\n\nطريقة الشرح : ممتازة جدًا… من أفضل الدكاترة اللي مروا علي من هذه الناحية… لدرجة أنه في أشياء من ثيرمو ١ ما كنت فاهمها و فهمتها الحين معه و برضو في اشياء ما كنت مدرك قيمتها كالبروسيس جراف (T-s,P-v…etc)\nيشرح على السلايدات و ما يستخدم السبورة إلا نادرًا\nالجميل أيضًا أنه أول ثلاث أسابيع سوا مراجعة شاملة كاملة لثيرمو ١ و كانت مفيدة جدًا\nبالإضافة إلى أنه قبل بداية الشرح يسوي مراجعة سريعة للي شرحه الكلاس الماضي\n\nالكويزات :\nمتوسطة الصعوبة… في مرة جاب لنا نسخ لصق من الهومورك و في مرات يجيب قريبة من الهومورك و المرات لا كذا ولا كذا… بشكل عام إذا حليت الهومورك لحالك أو على الأقل فاهمه زين بتحل زين\n+\nعطانا كويز عليه بونس آخر الفصل\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: أفرج سكشن الكورس و للأمانة ضبطنا بالقريد النهائي… أما قريد الدكتور النهائي فأتركه لكم\n\nالصوت: واضح جدًا و يسوي ميكس عربي إنجليزي… الدكتور من الحجاز\n\nإضافات :\n\nالزبدة…\n\nشرحه أسطوري\nتصحيحه جيد\nمحترم جدًا\nمتعاون بمواعيد الكويز\nعطانا أوف تعويض الميجر\n\nالتحضير كما سبق و ذكرت\nغير متعاون بتسليم الهومورك… الأحد يعني الأحد و هوموركاته أسبوعية\nما يتواصل مع الطلاب على الايميل كثير (مثلًا موعد و مكان الميجر)\nالتصحيح بطيء\n\nسلايدته موجودة هنا: (ممتازة)\nNew Page 1\n\nكويزاته ما يرجعها و لا يرفعها… مو موجودة عندي\n\nالسيلابس:\nME 204 syllabus - 162 | تحميل\n\nلما سجلت عنده للأسف سمعت و قرأت تهويل عن الدكتور و بالأخير طلع الدكتور ممتاز… إذا شفته بأي كورس مستقبلي لن أتردد بالتسجيل معه… الله يسعده\n\nإن شاء الله ما أكون نسيت شي 😅", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474710-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/haitham-ba-haidarah/98201/7", "user": "M_nd_m", "ts": 1496862162000, "tid": 98201, "pn": 7}}]}', 1496862162000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-majed_als-me204', 'stk-majed_als', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98201", "n": "Dr. Haitham Ba-Haidarah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204 - 192\nما قد شفت دكتور متشدد بالتحضير نفسه. تدخل بعد دقيقة يعطيك ليت.\nما اقدر احكم عليه بالتصحيح لأني أخذت المادة NP.\nبالنسبة للشرح، الدكتور يشرح كونسبت فقط!\nالمادة كلها مسائل وتحتاج حل، لكن الدكتور ما كتب على السبورة الا مرة وحدة بس خلال الترم.\nكله كلام في كلام، واذا جاء الاختبار تبلش بنفسك.\nطبعا المادة مشروحة بشكل كامل باليوتيوب عن طريق د. محمد شايع وهو أفضل مصدر للمذاكرة.\nاعطانا بروجكت خفيف وفكرته حلوه بنهاية الترم ( موجود على kfupm resources )\nما أنصحك تنزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526540-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/haitham-ba-haidarah/98201/8", "user": "majed_als", "ts": 1604632820000, "tid": 98201, "pn": 8}}]}', 1604632820000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_ali_bajabaau-me204', 'stk-omar_ali_bajabaau', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98201", "n": "Dr. Haitham Ba-Haidarah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204 - TERM 192\nالنصف الثاني من الترم صار اونلاين.\n\nجميع ماذكروه اخواني في التعليقات السابقة صحيحة واتفق معهم فيها جميعها، وابغا اضف عليها الآتي:\n\nطريقة الشرح : شرحه جميل بس كان يجيب النوم لان صوته نفس النبرة طول الكلاس\n\nالفاينلات :ماكان فيه لانه لما صار الوضع اونلاين كل شيئ اتلخبط فاضطر الدكتور انه يعمل oral exam للي مجموعه ماتعدى النجاح. (مااتذكر من كم كان النجاح وقتها بس كانت حول ال50 اذا ماخاب ظني)\n\nالصوت: صوت يجيب النوم بسبب انه النبرة ثابتة بس واضحة وتقدر تركز معاه.\n\nإضافات : الدكتور طيب هادئ ورايق ولهجته حجااازية مكاااوية وهذا الي عجبني فيه لاني جداوي 🤠. مايحب يشوف احد ع الجوالات ويبغا الطلاب يهتموا ويركزوا معاه. اذا انت مهتم انك تفهم ومجتهد نزل عنده، لكن اذا ماتحب الكرف انصحك تبعد لانه مع ذا الدكتور (في رأيي) تحتاج جهد شخصي. عن نفسي اذا لقيت اسمه في اي مادة رح انزلها عنده وانا مغمض.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527732-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/haitham-ba-haidarah/98201/9", "user": "Omar_Ali_BajabaaU", "ts": 1610191964000, "tid": 98201, "pn": 9}}]}', 1610191964000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_mm-me204', 'stk-omar_mm', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f98402", "n": "Dr. Anas Salhab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me204 Lec Term 151\nدكتور اخلاق وطيب … يحضر ف نهاية الكلاس كان في شباب كثير يجو متأخر ويحضرهم\nشرحه طيب ويسوي اللي عليه كويزاته فيها الصعب وفيها السهل … يهتم بمصلحة الطالب وكان يقول حتى اللي عنده مشكلة باللاب يجيني\n\nصرااحه كنت مرتاح مع الدكتور أنس ف الكورس\nأعطيه A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1446598-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/anas-salhab/98402/10", "user": "Omar_Mm", "ts": 1460572196000, "tid": 98402, "pn": 10}}]}', 1460572196000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahm2d1-me204', 'stk-ahm2d1', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f118632", "n": "Dr. Saad Mansoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 201 - ME 204\n\nالتحضير : كان ياخذ التحضير من البلاك بورد\n\nطريقة الشرح : شرحه ممتاز وكويس في البدايه يشرح الكونسبت ويعلمك القوانين وبعدها يعطيك امثله\n\nالكويزات : كانت سهله الى متوسطه اذا مذاكر زين بتحلها\n\nالمياجر: في الترم هذا صار النظام الدكتور هو اللي يحط الميد والفاينل وكان الميد سهل تقريبا ( كان كله رتن )\n\nالفاينلات : كان MCQ + رتن. الرتن كان سهل الى متوسط وال mcq كان صعب مره\n\nالصوت: صوته واضح\n\nإضافات : الدكتور ممتاز وكان مريحنا في الاون لاين ومتساعد كثيييييير لايفوتك اذا اون لاين بس المشكله كانت في الفاينل قريد تقريبا كان الافرج عنده C+ وممكن دكتور غيره يكون B + يطول في التصحيح ياخذ حول اسبوعين وتصحيحه يعطيك حقك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527477-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saad-mansoor/118632/30", "user": "Ahm2d1", "ts": 1609564020000, "tid": 118632, "pn": 30}}]}', 1609564020000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mewarrior-me204', 'stk-mewarrior', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f118637", "n": "Dr. Obaidallah Munteshari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204 - 221\n\nبنود التقييم :\n\nالتحضير : غالبا اخر الكلاس\nطريقة الشرح : سلايدات وحل امثلة, يرحب بالاسئلة اثناء الشرح\nالكويزات : متوسطة واتوقع انها من الهوموورك, عطانا اذا ماخانتني الذاكرة خمس كويزات وحذف اقل اثنين\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A+\nالصوت: واضح ويشرح غالبا بالانقليزي مع تأكيدات لبعض المفاهيم بالعربي\nإضافات : الله يسعده وين ما راح, يده ثقيلة كرما بالدرجات والقريدات وخفيفة بالتصحيح بشكل غير طبيعي\n\nسكشن الدكتور من الاخر ما يتفوت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536138-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/obaidallah-munteshari/118637/11", "user": "MeWarrior", "ts": 1673209854000, "tid": 118637, "pn": 11}}]}', 1673209854000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-me204', 'stk-moh_ammed', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f118642", "n": "Dr. Abdullah Al-Sharafi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204 - Term 212\nالتحضير: يحضر بداية كل محاضرة، واللي يجي متأخر يروح للدكتور يحضره بنهاية المحاضرة بس يخليه ليت…بداية الترم -ولفترة بسيطة- كان يمرر ورقة توقيع عشان نحضر، بس بعدين صار ينادي بالرقم التسلسلي.\n\nالشرح: جدا واضح وممتع.\n\nالتعامل: الدكتور حبيب ودايم يضحك مع الطلاب في وسط الشرح ويغير الجو.\n\nالصوت: واضح، ويتكلم بخليط من العربي والانجليزي.\n\nالكويزات: بصراحة عكس اللي توقعته، الكويزات سهلة والدكتور جدا متعاون معنا فيها لدرجة إنه ألغى كويزين عشانه شافنا جايبين العيد فيهم…الزبدة إن الكويزات أشوفها سهلة ومايبي لها ذيك المذاكرة.\n\nإضافات: الدكتور يهتم جدا لطلابه ويحب الطالب اللي يكون منتبه معاه في الدرس، لذلك لاتفكر تستخدم جوالك أو تاخذ لك غفوة وسط الشرح لأنه راح يصحيك ويخليك تغسل وجهك بعد.\nسمعت بعض الطلاب يقولون تصحيحه سيء، بس والله تصحيحه جميل وممكن يعطيك فوق حقك.\nالدكتور يتقبل الأسئلة جدا وماتحسه يطفش منها حتى لو كثرت.\nتقدر تلقى سلايداته في الريسورسز.\n\nبعض السلبيات: الدكتور كان ياخذ وقت زيادة على المحاضرة ويأخرك لو كان عندك محاضرة بعدها في مبنى بعيد…يعني شيء طبيعي ياخذ له 5 دقايق فوق وقت المحاضرة. أيضا، الدكتور أحيانا يخليك تداوم محاضرات إضافية في الليل بس عشان تخلصون المنهج أو تاخذون كويز، سواها فينا مرتين.\n\nالقريد النهائي: A+++ ولو شفته في مادة ثانية بنزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534557-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-sharafi/118642/10", "user": "Moh_ammed", "ts": 1654352002000, "tid": 118642, "pn": 10}}]}', 1654352002000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mo2015-me204', 'stk-mo2015', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f118647", "n": "Dr. Bilal Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "181-me 204\n\nالتحضير : تحضر نفسك بالورقة ولا كان عنده تعليق على التأخير\n\nطريقة الشرح : أشوفها ممتازة ، يشرح المفاهيم و المادة ، يستخدم الاسلايدات ، ويحل على السبورة .\n\nالكويزات : تكون 1 MCQ عليه درجتين وسؤال ،\nالكوز يكون بسيط نوعا ما ولا يحتاج حل كثير .\n\nالصوت : واضح\n\nصراحة أعجبني المدرس بطريقة شرحه وإسلوبه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1502571-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bilal-qureshi/118647/5", "user": "MO2015", "ts": 1542553111000, "tid": 118647, "pn": 5}}]}', 1542553111000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rm121-me204', 'stk-rm121', 'ME 204', 'doc', '{"docs": [{"id": "stk-dr-f182519", "n": "Dr. Awad Alquaity", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 204 - Term 202\n\nالتحضير :\n\nيحضر عن طريق تيمز ما ينادي بالاسماء ولا شي\n\nطريقة الشرح :\n\nيفتح سلايداته ويبدا يمشي سلايده سلايده ويشرح ، سلايداته حلوه وفيها اقزامبلز وكونسبت واشوفها الافضل ، شرحه بنظري ممتاز بس البعض كان يعاني من سرعته بالكلام ، الدكتور يحب احيانا انكم تشاركون معه. ويبدا يسال اسئله لكن ما يحدد طالب معين يجاوب\n\nالكويزات :\n\nاخذنا اعتقد ٦ او ٥ كوزات وحذف لنا اسوء واحد ، كوزاته ٩٠٪؜ منها كونسبت وجدا تافهه اذا كنت قاري السلايدات ، هديه بالعربي وعليها٨٪؜\n\nعنده برضو pop-quiz عليه ٢٪؜ ، البوب كويز عباره عن كويز قصير بعد لكتشر معينه يكون توه شارحها ، يعني مثلا يقولكم الاسبوع هذابيكون فيه بوب كويز بعد واحد من الكلاسات\n\nالمياجر:\n\nكان ميد هو كاتبه عباره عن ٥ اسئله ، بنظري اشوفه جدا سهل مقارنةً بباقي الدكاتره\n\nالفاينلات :\n\nهو كاتبه برضو ، كان جزئين الاول خيارات شامل الكتاب كامل\n\nالثاني كان رتن ٣ اسئله شامله التشابترات الي بعد الميد\n\nالرتن كان متوسط الصعوبه لكن الخيارات اشوفها صعبه صراحه ، ممكن كان يبي ينزل الافرج او شي\n\nالقريد النهائي:\n\nA++++++++ ولو فيه اكثر عطيته\n\nالصوت:\n\nواضح ولكن كلامه سريع بالنسبه للبعض\n\nإضافات :\n\nالدكتور بدون مقارنه من افضل الدكاتره الي درسوني في الجامعه اذا ما كان الافضل ، ولا اعتقد بشوف مثله ، ولو فيه كورس ثاني يدرسه راح اسجل عنده وانا مغمض ومتطمن ، غير ان شرحه ممتاز واخلاق … الدكتور جدا جدا جدا مراعي لظروف الطالب ابدا ما عانينا معاه ولا عمره حسسنا بضغط زايد عن الحد ، يعتبر من الاقلّه الي ممكن تضحي بوقت الكلاس عشانه\n\nبخصوص توزيع القريدات ، كان اقرب للستاندرد ، الA كان من ٨٧ تقريبا والA+ حول ال٩٢ اعتقد والله اعلم\n\nافرج السكشنين كان ٧٣ و ٧٧ … مرتفع نسبيا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530365-me204", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/awad-alquaity/182519/3", "user": "RM121", "ts": 1622881282000, "tid": 182519, "pn": 3}}]}', 1622881282000, 1794826869, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
